const SOURCES = {
  cities: "https://raw.githubusercontent.com/datasets/world-cities/main/data/world-cities.csv",
  animals: "https://raw.githubusercontent.com/jneidel/animal-names/master/animals-unfiltered.txt",
  colors: "https://raw.githubusercontent.com/jonathantneal/color-names/master/color-names.json",
  objects: "https://raw.githubusercontent.com/dariusk/corpora/master/data/objects/objects.json",
  fruits: "https://raw.githubusercontent.com/mybkgjvgnd/Fruit-306-Dataset/main/README.md"
};

function normalizeKey(value) {
  return String(value || "")
    .trim()
    .toLocaleLowerCase("es")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function cleanValue(value) {
  return String(value || "")
    .replace(/_/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function unique(values) {
  const map = new Map();
  for (const raw of values || []) {
    const value = cleanValue(raw);
    if (!value || value.length > 80) continue;
    const k = normalizeKey(value);
    if (!map.has(k)) map.set(k, value);
  }
  return [...map.values()].sort((a,b)=>a.localeCompare(b,"es"));
}

async function fetchText(url, timeoutMs=18000) {
  const controller = new AbortController();
  const timer = setTimeout(()=>controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: { "User-Agent": "TutifrutiGame/1.0" }
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.text();
  } finally {
    clearTimeout(timer);
  }
}

function parseCSVLine(line) {
  const out=[];
  let value="", quoted=false;
  for(let i=0;i<line.length;i++) {
    const c=line[i];
    if(c === '"') {
      if(quoted && line[i+1] === '"') { value+='"'; i++; }
      else quoted=!quoted;
    } else if(c === ',' && !quoted) {
      out.push(value); value="";
    } else value+=c;
  }
  out.push(value);
  return out;
}

async function loadCities() {
  const txt = await fetchText(SOURCES.cities);
  const lines = txt.split(/\r?\n/).filter(Boolean);
  if(lines.length < 2) return [];
  const header=parseCSVLine(lines[0]).map(x=>x.trim().toLowerCase());
  const idx=header.indexOf("name");
  if(idx<0) return [];
  const values=[];
  for(let i=1;i<lines.length;i++) {
    const row=parseCSVLine(lines[i]);
    if(row[idx]) values.push(row[idx]);
  }
  return values;
}

async function loadAnimals() {
  const txt = await fetchText(SOURCES.animals);
  return txt.split(/\r?\n/)
    .map(x=>x.trim())
    .filter(x=>x && !/^[A-Z]top$/i.test(x));
}

async function loadColors() {
  const txt = await fetchText(SOURCES.colors);
  const obj=JSON.parse(txt);
  return Object.values(obj);
}

async function loadObjects() {
  const txt = await fetchText(SOURCES.objects);
  const obj=JSON.parse(txt);
  return Array.isArray(obj.objects) ? obj.objects : [];
}

async function loadFruits() {
  const txt = await fetchText(SOURCES.fruits);
  // The Fruit-306 README lists fruit/category names in backticks.
  const values=[];
  const rx=/`([^`]+)`/g;
  let m;
  while((m=rx.exec(txt))) {
    const v=m[1].trim();
    if(
      v.length >= 2 &&
      v.length <= 60 &&
      !v.includes("/") &&
      !v.includes(".") &&
      !v.includes("http") &&
      !/^\d+$/.test(v)
    ) values.push(v);
  }
  return values;
}

export const DATABASE = {
  Nombre: unique(LOCAL_DATABASE["Nombre"]),
  Apellido: unique(LOCAL_DATABASE["Apellido"]),
  País: unique(LOCAL_DATABASE["País"]),
  Ciudad: unique(LOCAL_DATABASE["Ciudad"]),
  Animal: unique(LOCAL_DATABASE["Animal"]),
  Fruta: unique(LOCAL_DATABASE["Fruta"]),
  Color: unique(LOCAL_DATABASE["Color"]),
  Objeto: unique(LOCAL_DATABASE["Objeto"])
};


async function loadWikidataObjects() {
  const query = `
SELECT DISTINCT ?itemLabel WHERE {
  ?item wdt:P279* wd:Q223557 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "es,en". }
}
LIMIT 5000`;
  const url = "https://query.wikidata.org/sparql?format=json&query=" + encodeURIComponent(query);
  const txt = await fetchText(url, 25000);
  const data = JSON.parse(txt);
  return (data.results?.bindings || [])
    .map(x => x.itemLabel?.value)
    .filter(Boolean);
}

const jobs = [
  ["Ciudad", loadCities],
  ["Animal", loadAnimals],
  ["Fruta", loadFruits],
  ["Color", loadColors],
  ["Objeto", async()=>[...(await loadObjects()), ...(await loadWikidataObjects())]]
];

for (const [category, loader] of jobs) {
  try {
    const external = await loader();
    DATABASE[category] = unique([...DATABASE[category], ...external]);
    console.log(`[DB] ${category}: ${DATABASE[category].length} registros`);
  } catch (err) {
    console.warn(`[DB] No se pudo ampliar ${category}: ${err.message}. Se usa base local (${DATABASE[category].length}).`);
  }
}

console.log("[DB] Base Tutifruti lista.");
